class Time {
    _time;
    _hours;
    _days;
    constructor() {
        this._time = 8;
        this._hours = 0;
        this._days = 0;
    }
    getDays() {
        return this._days;
    }
    getTime() {
        return this._time;
    }
    addHours(hours = 1) {
        this._hours += hours;
        this._days = Math.floor((this._hours + 8) / 24);
        let t = 8 + this._hours;
        console.log(24 * this._days);
        console.log(t);
        if (t > 24) {
            this._time = t - (24 * this._days);
        }
        else {
            this._time = t;
        }
    }
    subHours(hours = 1) {
        this._hours -= hours;
        this._days = Math.floor(this._hours / 24);
    }
    getHours() {
        return this._hours;
    }
}
export default Time;
